// Price the request and build a branded HTML quote page.
const f = $input.first().json;
const PACKAGES = {
  'Single workflow (2-3 apps)':         { base: 200, days: 4 },
  'AI chatbot / booking bot':           { base: 400, days: 6 },
  'Shopify automation':                 { base: 250, days: 5 },
  'Zapier/Make to n8n migration':       { base: 300, days: 5 },
};
const pkgName = f['What do you want to automate?'];
const pkg = PACKAGES[pkgName] || PACKAGES['Single workflow (2-3 apps)'];
const apps = Math.max(1, parseInt(f['How many apps need to connect?'], 10) || 2);
const extrasRaw = f['Extras'];
const extras = Array.isArray(extrasRaw) ? extrasRaw : (extrasRaw ? [extrasRaw] : []);

const lines = [{ item: pkgName || 'Single workflow (2-3 apps)', amount: pkg.base }];
const extraApps = Math.max(0, apps - 3);
if (extraApps) lines.push({ item: `${extraApps} additional app integration(s) x $50`, amount: extraApps * 50 });
if (extras.includes('Self-hosted n8n setup')) lines.push({ item: 'Self-hosted n8n setup (VPS, SSL, backups)', amount: 150 });
let oneTime = lines.reduce((s, l) => s + l.amount, 0);
let days = pkg.days + extraApps;
if (extras.includes('Rush delivery (48h)')) {
  const fee = Math.round(oneTime * 0.25);
  lines.push({ item: 'Rush delivery (48h) +25%', amount: fee });
  oneTime += fee;
  days = 2;
}
const monthly = extras.includes('Monthly maintenance') ? 100 : 0;

const now = DateTime.now().setZone('Asia/Ho_Chi_Minh');
const quoteNo = 'Q-' + now.toFormat('yyyyLLdd') + '-' + Math.floor(1000 + Math.random() * 9000);
const valid = now.plus({ days: 14 }).toFormat('d LLL yyyy');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const usd = n => '$' + n.toLocaleString('en-US');
const name = f['Your name'], email = f['Work email'], company = f['Company'] || '';

const rows = lines.map(l => `<tr><td>${esc(l.item)}</td><td class="num">${usd(l.amount)}</td></tr>`).join('');
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Quote ${quoteNo} - 03 Flow Forge</title>
<link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@700&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">
<style>
:root{--navy:#2A364B;--coral:#F06E52;--coral-l:#FE8D71;--blue:#9CC3ED;--bg:#FAFBFD;--grey:#5F6A7D;--line:#E3E8F0}
*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Inter,system-ui,sans-serif;color:var(--navy)}
.wrap{max-width:720px;margin:32px auto;padding:0 16px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;overflow:hidden}
.head{padding:28px 32px;border-bottom:4px solid var(--coral);display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap}
.brand{font-family:Montserrat,sans-serif;font-size:26px;letter-spacing:.5px}.brand b{color:var(--coral-l)}.tag{color:var(--grey);font-size:13px;margin-top:4px}
.meta{text-align:right;font-size:13px;color:var(--grey)}.meta strong{display:block;color:var(--navy);font-size:15px}
.body{padding:28px 32px}h2{font-size:18px;margin:0 0 4px}p{margin:0 0 16px;line-height:1.55}
table{width:100%;border-collapse:collapse;margin:8px 0 20px}td{padding:12px 0;border-bottom:1px solid var(--line);font-size:15px}.num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
.total td{border-bottom:none;font-weight:600;font-size:18px;padding-top:16px}.total .num{color:var(--coral)}
.pills{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}.pill{background:rgba(156,195,237,.25);border-radius:999px;padding:8px 14px;font-size:14px}
.next{background:var(--bg);border-radius:8px;padding:16px 20px;font-size:14px;line-height:1.6}.foot{padding:16px 32px;color:var(--grey);font-size:12px;border-top:1px solid var(--line)}
@media(max-width:560px){.meta{text-align:left}.head,.body,.foot{padding-left:20px;padding-right:20px}}
</style></head><body><div class="wrap"><div class="card">
<div class="head"><div><div class="brand"><b>03</b> FLOW FORGE</div><div class="tag">Workflows that run while you sleep.</div></div>
<div class="meta"><strong>Quote ${quoteNo}</strong>Valid until ${valid}</div></div>
<div class="body"><h2>Hi ${esc(String(name).split(' ')[0])},</h2>
<p>Thanks for your request${company ? ' for ' + esc(company) : ''}. Here is your estimate for <strong>${esc(pkgName)}</strong> connecting ${apps} app(s).</p>
<table>${rows}<tr class="total"><td>Total (one-time)</td><td class="num">${usd(oneTime)}</td></tr></table>
<div class="pills"><span class="pill">Delivery: ${days} working days</span>${monthly ? `<span class="pill">Maintenance: ${usd(monthly)}/month</span>` : ''}<span class="pill">Includes video handover</span></div>
<div class="next"><strong>Next steps</strong><br>1. We will email you at ${esc(email)} within 24 hours to confirm scope.<br>2. Have 2-3 real examples of your data ready for a 15-minute call.<br>3. Work starts once you accept the offer on Upwork.</div></div>
<div class="foot">Estimate only. Third-party costs (n8n Cloud, AI usage, hosting) are billed to your own accounts. 03 Flow Forge &middot; 3flowforge@gmail.com</div>
</div></div></body></html>`;

return [{ json: {
  quote_no: quoteNo, name, email, company, package: pkgName, apps, extras: extras.join(', '),
  one_time: oneTime, monthly, delivery_days: days, created_at: now.toFormat('yyyy-LL-dd HH:mm'), html,
} }];
